import{_ as e,c as t,o as r,ag as l}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"Exportera taggar","description":"","frontmatter":{},"headers":[],"relativePath":"10-projekthantering/exportera-taggar.md","filePath":"10-projekthantering/exportera-taggar.md","lastUpdated":1768470380000}'),i={name:"10-projekthantering/exportera-taggar.md"};function n(o,a,s,p,d,g){return r(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="exportera-taggar" tabindex="-1">Exportera taggar <a class="header-anchor" href="#exportera-taggar" aria-label="Permalink to &quot;Exportera taggar&quot;">​</a></h1><p>TIA Portal låter dig exportera och importera taggar och andra data till Excel-format. Detta förenklar massredigering och dokumentation.</p><h2 id="exportera-plc-taggar-till-excel" tabindex="-1">Exportera PLC-taggar till Excel <a class="header-anchor" href="#exportera-plc-taggar-till-excel" aria-label="Permalink to &quot;Exportera PLC-taggar till Excel&quot;">​</a></h2><h3 id="steg-for-steg-export" tabindex="-1">Steg-för-steg export <a class="header-anchor" href="#steg-for-steg-export" aria-label="Permalink to &quot;Steg-för-steg export&quot;">​</a></h3><ol><li>Öppna <strong>PLC tags</strong> i projektträdet</li><li>Högerklicka på tagg-tabellen du vill exportera</li><li>Välj <strong>Export...</strong></li><li>Välj filformat (Excel, CSV)</li><li>Ange filnamn och plats</li><li>Klicka <strong>Export</strong></li></ol><h3 id="exportformat" tabindex="-1">Exportformat <a class="header-anchor" href="#exportformat" aria-label="Permalink to &quot;Exportformat&quot;">​</a></h3><p>TIA Portal exporterar till <code>.xlsx</code>-format med följande kolumner:</p><table tabindex="0"><thead><tr><th>Kolumn</th><th>Beskrivning</th><th>Exempel</th></tr></thead><tbody><tr><td>Name</td><td>Taggnamn</td><td>Motor1_Start</td></tr><tr><td>Path</td><td>Sökväg</td><td>Default tag table</td></tr><tr><td>Data Type</td><td>Datatyp</td><td>Bool</td></tr><tr><td>Logical Address</td><td>Adress</td><td>%M0.0</td></tr><tr><td>Comment</td><td>Kommentar</td><td>Startknapp motor 1</td></tr><tr><td>Hmi Visible</td><td>Synlig i HMI</td><td>TRUE/FALSE</td></tr><tr><td>Hmi Accessible</td><td>Tillgänglig i HMI</td><td>TRUE/FALSE</td></tr></tbody></table><h3 id="exportera-alla-tabeller" tabindex="-1">Exportera alla tabeller <a class="header-anchor" href="#exportera-alla-tabeller" aria-label="Permalink to &quot;Exportera alla tabeller&quot;">​</a></h3><p>För att exportera flera tabeller samtidigt:</p><ol><li>Markera <strong>PLC tags</strong>-mappen</li><li>Högerklicka &gt; <strong>Export...</strong></li><li>Alla tabeller exporteras till samma fil</li></ol><h2 id="redigera-i-excel" tabindex="-1">Redigera i Excel <a class="header-anchor" href="#redigera-i-excel" aria-label="Permalink to &quot;Redigera i Excel&quot;">​</a></h2><h3 id="fordelar-med-excel-redigering" tabindex="-1">Fördelar med Excel-redigering <a class="header-anchor" href="#fordelar-med-excel-redigering" aria-label="Permalink to &quot;Fördelar med Excel-redigering&quot;">​</a></h3><ul><li>Snabb massredigering av många taggar</li><li>Kopiera/klistra in från andra källor</li><li>Sök och ersätt</li><li>Sortera och filtrera</li><li>Formelberäkningar</li></ul><h3 id="lagga-till-nya-taggar-i-excel" tabindex="-1">Lägga till nya taggar i Excel <a class="header-anchor" href="#lagga-till-nya-taggar-i-excel" aria-label="Permalink to &quot;Lägga till nya taggar i Excel&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Exempel: Skapa 10 motortaggar</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name            | Data Type | Address | Comment</span></span>
<span class="line"><span>----------------|-----------|---------|------------------</span></span>
<span class="line"><span>Motor1_Start    | Bool      | %M0.0   | Start motor 1</span></span>
<span class="line"><span>Motor1_Stop     | Bool      | %M0.1   | Stopp motor 1</span></span>
<span class="line"><span>Motor1_Running  | Bool      | %M0.2   | Motor 1 kör</span></span>
<span class="line"><span>Motor2_Start    | Bool      | %M0.3   | Start motor 2</span></span>
<span class="line"><span>...</span></span></code></pre></div><h3 id="tips-for-effektiv-redigering" tabindex="-1">Tips för effektiv redigering <a class="header-anchor" href="#tips-for-effektiv-redigering" aria-label="Permalink to &quot;Tips för effektiv redigering&quot;">​</a></h3><ul><li>Använd Excel-formler för att generera adresser</li><li>Kopiera format från befintliga taggar</li><li>Behåll kolumnordningen exakt</li></ul><div class="warning custom-block"><p class="custom-block-title">Varning</p><p>Ändra INTE kolumnrubriker eller format - TIA Portal kräver exakt matchning vid import!</p></div><h2 id="importera-taggar-fran-excel" tabindex="-1">Importera taggar från Excel <a class="header-anchor" href="#importera-taggar-fran-excel" aria-label="Permalink to &quot;Importera taggar från Excel&quot;">​</a></h2><h3 id="steg-for-steg-import" tabindex="-1">Steg-för-steg import <a class="header-anchor" href="#steg-for-steg-import" aria-label="Permalink to &quot;Steg-för-steg import&quot;">​</a></h3><ol><li>Öppna tagg-tabellen i TIA Portal</li><li>Högerklicka &gt; <strong>Import...</strong></li><li>Välj Excel-filen</li><li>Granska förhandsvisning</li><li>Klicka <strong>Import</strong></li></ol><h3 id="importalternativ" tabindex="-1">Importalternativ <a class="header-anchor" href="#importalternativ" aria-label="Permalink to &quot;Importalternativ&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Alternativ</th><th>Beskrivning</th></tr></thead><tbody><tr><td>Add tags</td><td>Lägg till nya taggar</td></tr><tr><td>Overwrite</td><td>Ersätt befintliga med samma namn</td></tr><tr><td>Compare</td><td>Visa skillnader innan import</td></tr></tbody></table><h3 id="hantera-importfel" tabindex="-1">Hantera importfel <a class="header-anchor" href="#hantera-importfel" aria-label="Permalink to &quot;Hantera importfel&quot;">​</a></h3><p>Vanliga fel vid import:</p><ul><li><strong>Duplicate name</strong>: Taggnamn finns redan</li><li><strong>Invalid data type</strong>: Datatypen stöds ej</li><li><strong>Address conflict</strong>: Adressen används redan</li></ul><h2 id="exportera-datablock" tabindex="-1">Exportera datablock <a class="header-anchor" href="#exportera-datablock" aria-label="Permalink to &quot;Exportera datablock&quot;">​</a></h2><h3 id="db-till-excel" tabindex="-1">DB till Excel <a class="header-anchor" href="#db-till-excel" aria-label="Permalink to &quot;DB till Excel&quot;">​</a></h3><p>Datablocks exporteras separat:</p><ol><li>Högerklicka på datablocket</li><li>Välj <strong>Generate source from blocks</strong></li><li>Väljer <code>.db</code>-format (textbaserat)</li></ol><p>Alternativt för tabelldata:</p><ol><li>Öppna datablocket</li><li>Markera data du vill exportera</li><li>Kopiera (Ctrl+C)</li><li>Klistra in i Excel</li></ol><h2 id="exportera-hmi-taggar" tabindex="-1">Exportera HMI-taggar <a class="header-anchor" href="#exportera-hmi-taggar" aria-label="Permalink to &quot;Exportera HMI-taggar&quot;">​</a></h2><h3 id="hmi-tags" tabindex="-1">HMI Tags <a class="header-anchor" href="#hmi-tags" aria-label="Permalink to &quot;HMI Tags&quot;">​</a></h3><p>HMI-taggar exporteras på liknande sätt:</p><ol><li>Öppna HMI-enheten &gt; <strong>HMI tags</strong></li><li>Högerklicka &gt; <strong>Export...</strong></li><li>Välj filformat och plats</li></ol><h3 id="hmi-specifika-falt" tabindex="-1">HMI-specifika fält <a class="header-anchor" href="#hmi-specifika-falt" aria-label="Permalink to &quot;HMI-specifika fält&quot;">​</a></h3><p>HMI-export inkluderar extra kolumner:</p><ul><li>Acquisition cycle (uppdateringsintervall)</li><li>Connection (PLC-anslutning)</li><li>PLC tag (kopplad PLC-tagg)</li></ul><h2 id="praktiska-anvandningsomraden" tabindex="-1">Praktiska användningsområden <a class="header-anchor" href="#praktiska-anvandningsomraden" aria-label="Permalink to &quot;Praktiska användningsområden&quot;">​</a></h2><h3 id="_1-dokumentation" tabindex="-1">1. Dokumentation <a class="header-anchor" href="#_1-dokumentation" aria-label="Permalink to &quot;1. Dokumentation&quot;">​</a></h3><p>Exportera taggar för att skapa dokumentation:</p><ul><li>Inkludera i teknisk rapport</li><li>Dela med kund eller kollega</li><li>Arkivera för framtida referens</li></ul><h3 id="_2-massandring" tabindex="-1">2. Massändring <a class="header-anchor" href="#_2-massandring" aria-label="Permalink to &quot;2. Massändring&quot;">​</a></h3><p>Ändra många taggar effektivt:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Scenario: Byt prefix på 100 taggar från &quot;M1_&quot; till &quot;Motor1_&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Exportera taggar</span></span>
<span class="line"><span>2. I Excel: Sök/Ersätt &quot;M1_&quot; → &quot;Motor1_&quot;</span></span>
<span class="line"><span>3. Importera tillbaka</span></span></code></pre></div><h3 id="_3-kopiera-mellan-projekt" tabindex="-1">3. Kopiera mellan projekt <a class="header-anchor" href="#_3-kopiera-mellan-projekt" aria-label="Permalink to &quot;3. Kopiera mellan projekt&quot;">​</a></h3><p>Återanvänd taggar i nya projekt:</p><ol><li>Exportera från källprojekt</li><li>Redigera vid behov</li><li>Importera till nytt projekt</li></ol><h3 id="_4-generera-fran-plc-lista" tabindex="-1">4. Generera från PLC-lista <a class="header-anchor" href="#_4-generera-fran-plc-lista" aria-label="Permalink to &quot;4. Generera från PLC-lista&quot;">​</a></h3><p>Om du har en I/O-lista från konstruktion:</p><ol><li>Formatera listan enligt TIA-export-format</li><li>Importera direkt till projektet</li><li>Spara timmar av manuellt arbete</li></ol><h2 id="exportera-andra-objekt" tabindex="-1">Exportera andra objekt <a class="header-anchor" href="#exportera-andra-objekt" aria-label="Permalink to &quot;Exportera andra objekt&quot;">​</a></h2><h3 id="textuella-kallor" tabindex="-1">Textuella källor <a class="header-anchor" href="#textuella-kallor" aria-label="Permalink to &quot;Textuella källor&quot;">​</a></h3><p>Programblock kan exporteras som text:</p><ol><li>Markera block</li><li><strong>External source files &gt; Generate source from blocks</strong></li><li>Redigera i valfri texteditor</li><li>Importera tillbaka</li></ol><h3 id="cross-reference" tabindex="-1">Cross-reference <a class="header-anchor" href="#cross-reference" aria-label="Permalink to &quot;Cross-reference&quot;">​</a></h3><p>Exportera korshänvisningar:</p><ol><li>Öppna Cross-reference-vyn</li><li>Markera all information</li><li>Kopiera till Excel</li></ol><h2 id="tips-och-tricks" tabindex="-1">Tips och tricks <a class="header-anchor" href="#tips-och-tricks" aria-label="Permalink to &quot;Tips och tricks&quot;">​</a></h2><h3 id="skapa-mall-fil" tabindex="-1">Skapa mall-fil <a class="header-anchor" href="#skapa-mall-fil" aria-label="Permalink to &quot;Skapa mall-fil&quot;">​</a></h3><ol><li>Exportera en tom eller minimal taggkonfiguration</li><li>Spara som mall</li><li>Använd som utgångspunkt för nya projekt</li></ol><h3 id="validera-innan-import" tabindex="-1">Validera innan import <a class="header-anchor" href="#validera-innan-import" aria-label="Permalink to &quot;Validera innan import&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kontrollera i Excel innan import:</span></span>
<span class="line"><span>□ Inga tomma rader</span></span>
<span class="line"><span>□ Inga duplicerade namn</span></span>
<span class="line"><span>□ Adresser i rätt format (%M0.0, %Q0.1, etc.)</span></span>
<span class="line"><span>□ Datatyper matchar (Bool, Int, Real, etc.)</span></span>
<span class="line"><span>□ Inga specialtecken i namn</span></span></code></pre></div><h3 id="automatisera-med-vba" tabindex="-1">Automatisera med VBA <a class="header-anchor" href="#automatisera-med-vba" aria-label="Permalink to &quot;Automatisera med VBA&quot;">​</a></h3><p>För återkommande uppgifter, skapa Excel-makro:</p><div class="language-vba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sub FormatagTIA()</span></span>
<span class="line"><span>    &#39; Generera sekventiella adresser</span></span>
<span class="line"><span>    Dim i As Integer</span></span>
<span class="line"><span>    For i = 1 To 100</span></span>
<span class="line"><span>        Cells(i + 1, 4).Value = &quot;%M&quot; &amp; (i \\ 8) &amp; &quot;.&quot; &amp; (i Mod 8)</span></span>
<span class="line"><span>    Next i</span></span>
<span class="line"><span>End Sub</span></span></code></pre></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109817218/updates-for-step-7-v18-s7-plcsim-v18-and-wincc-v18" target="_blank" rel="noreferrer">TIA Portal V18 Updates</a> - Import/export-funktioner</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><ul><li><a href="./spara-arkivera.html">Spara och arkivera</a> - Projekthantering</li><li><a href="./backup-versioner.html">Backup och versioner</a> - Säkerhetskopiering</li></ul>`,73)])])}const m=e(i,[["render",n]]);export{h as __pageData,m as default};
